function frameOf(format){
  format=String(format||'Start/Stop/Continue');
  if(format.indexOf('4L')>=0) return {cols:['Liked（喜欢）','Learned（学到）','Lacked（缺少）','Longed for（期望）'], intro:'四象限回顾，兼顾情绪与认知'};
  if(format.indexOf('Mad')>=0) return {cols:['Mad（气愤）','Sad（难过）','Glad（高兴）'], intro:'情绪导向回顾，适合团队气氛波动期'};
  return {cols:['Start（开始做）','Stop（停止做）','Continue（继续做）'], intro:'经典三栏回顾，通用性最强'};
}
function buildAgenda(minutes){
  minutes=parseInt(minutes,10)||60; if(minutes<30)minutes=30; if(minutes>180)minutes=180;
  return [
    ['开场与规则说明', 5],
    ['静默写便签（每人每列至少 1 条）', Math.max(10, Math.round(minutes*0.2))],
    ['轮流分享与分组归类', Math.max(15, Math.round(minutes*0.35))],
    ['投票选出 Top 1-3 改进项', Math.max(5, Math.round(minutes*0.15))],
    ['行动项确认（负责人 + 验收标准）', Math.max(10, Math.round(minutes*0.2))]
  ];
}
function buildRetro(o){
  o=o||{};
  var sprint=String(o.sprint||'').trim()||'本迭代';
  var format=String(o.format||'Start/Stop/Continue');
  var minutes=parseInt(o.minutes,10)||60;
  var size=parseInt(o.size,10)||6; if(size<3)size=3; if(size>20)size=20;
  var fr=frameOf(format);
  var agenda=buildAgenda(minutes);
  var lines=[];
  lines.push('# 迭代回顾：'+sprint);
  lines.push('');
  lines.push('## 一、会议信息');
  lines.push('- 形式：'+format+'（'+fr.intro+'）');
  lines.push('- 时长：'+minutes+' 分钟 · 人数：'+size+' 人');
  lines.push('');
  lines.push('## 二、议程（含 timebox）');
  agenda.forEach(function(a,i){ lines.push('- '+a[0]+'：'+a[1]+' 分钟'); });
  lines.push('');
  lines.push('## 三、便签模板');
  fr.cols.forEach(function(c){ lines.push('### '+c); lines.push('- （待填写）'); lines.push(''); });
  lines.push('## 四、行动项');
  lines.push('| 行动项 | 负责人 | 验收标准 | 截止日期 |');
  lines.push('| --- | --- | --- | --- |');
  lines.push('| （待填写） |  |  |  |');
  lines.push('');
  lines.push('> 提示：行动项控制在 1-3 条，下个迭代回顾时首先检视上轮行动项完成情况。');
  return {title:sprint+' 迭代回顾', colCount:fr.cols.length, agendaCount:agenda.length,
          agendaMinutes:agenda.reduce(function(s,a){return s+a[1];},0), markdown:lines.join('\n')};
}
var EXPORTS={frameOf:frameOf, buildAgenda:buildAgenda, buildRetro:buildRetro};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RetroForgePure = EXPORTS; }
